function expenseAccountForEmployee(p:WorkforceProfileV2025){if(p.job_family==='veterinarian'||p.job_family==='consultant')return ['5310','Veterinary Cost'];if(p.job_family==='factory_worker'||p.job_family==='production_supervisor')return ['5330','Factory Direct Labor'];if(p.job_family==='driver')return ['5410','Field Travel & Transport'];if(p.job_family==='sales'||p.job_family==='marketing')return ['5810','Sales Commissions'];return ['5300','Labor Cost'];}
export function approvePayrollPeriodV2025(state:WorkforcePayrollStateV2025,web:EnterpriseWebStateV202,mb:MultiBusinessEnterpriseStateV2023,periodId:string,actor:string):{state:WorkforcePayrollStateV2025;web:EnterpriseWebStateV202}{const period=state.payroll_periods.find(x=>x.id===periodId);if(!period)throw new Error('payroll_period_not_found');if(period.status!=='draft'&&period.status!=='reviewed')throw new Error('payroll_period_not_approvable');const lines=state.payroll_lines.filter(x=>x.payroll_period_id===period.id);if(!lines.length)throw new Error('payroll_lines_required');let nextWeb=ensureWorkforceFinanceV2025(web,mb,state),nextState=state;for(const line of lines){const p=requireProfile(nextState,line.employee_id),[acc,name]=expenseAccountForEmployee(p);const grossSar=currencyAmountToSar(line.gross_pay,line.exchange_rate_to_sar),alloc=line.cost_allocations.length?line.cost_allocations:[{business_unit_id:line.business_unit_id,allocation_percent:100,amount_sar:grossSar}];const journalLines=alloc.map(a=>({account_code:acc,account_name:name,debit_sar:a.amount_sar,credit_sar:0,cost_center_id:a.cost_center_id,counterparty:p.employee_id,memo:`Payroll ${period.period_code}`}));if(line.advance_recovery>0)journalLines.push({account_code:'1150',account_name:'Employee Advances',debit_sar:0,credit_sar:line.advance_recovery,cost_center_id:alloc[0]?.cost_center_id,counterparty:p.employee_id,memo:'Advance recovery'});if(line.other_deductions>0)journalLines.push({account_code:'2150',account_name:'Employee Deductions Payable',debit_sar:0,credit_sar:line.other_deductions,cost_center_id:alloc[0]?.cost_center_id,counterparty:p.employee_id,memo:'Other deductions'});journalLines.push({account_code:'2100',account_name:'Payroll Payable',debit_sar:0,credit_sar:line.net_pay_sar,cost_center_id:alloc[0]?.cost_center_id,counterparty:p.employee_id,memo:`Net payroll ${period.period_code}`});nextWeb=postJournalV202(nextWeb,{journal_date:period.date_to,description:`Payroll ${period.period_code} - ${p.full_name}`,source_type:'payroll_v20_2_5',source_id:line.id,original_currency:line.currency,original_amount:line.gross_pay,exchange_rate_to_sar:line.exchange_rate_to_sar,rate_date:period.date_to,lines:journalLines,created_by:actor,approved_by:actor},'finance');const je=nextWeb.journal_entries[0];nextState={...nextState,payroll_lines:nextState.payroll_lines.map(x=>x.id===line.id?{...x,status:'approved',journal_entry_id:je.id}:x)};let remaining=line.advance_recovery;if(remaining>0)nextState={...nextState,advances:nextState.advances.map(a=>{if(a.employee_id!==line.employee_id||a.status!=='recovering'||remaining<=0)return a;const applied=Math.min(a.balance_sar,remaining);remaining=round(remaining-applied);const bal=round(a.balance_sar-applied);return {...a,recovered_sar:round(a.recovered_sar+applied),balance_sar:bal,status:bal===0?'settled':'recovering'};})};}
const updatedPeriod={...period,status:'approved' as const,approved_by:actor,approved_at:now()};nextState=audit({...nextState,payroll_periods:nextState.payroll_periods.map(x=>x.id===period.id?updatedPeriod:x)},actor,'payroll_period_approve','payroll_period',period.id,period,updatedPeriod);return {state:nextState,web:nextWeb};}
export function payPayrollLineV2025(state:WorkforcePayrollStateV2025,mb:MultiBusinessEnterpriseStateV2023,web:EnterpriseWebStateV202,input:{payroll_line_id:string;treasury_account_id:string;payment_date:string;amount_sar?:number;paid_by:string}):{state:WorkforcePayrollStateV2025;multiBusiness:MultiBusinessEnterpriseStateV2023;web:EnterpriseWebStateV202;payment:PayrollPaymentV2025}{const line=state.payroll_lines.find(x=>x.id===input.payroll_line_id);if(!line)throw new Error('payroll_line_not_found');if(!['approved','partially_paid'].includes(line.status))throw new Error('payroll_line_not_payable');const period=state.payroll_periods.find(x=>x.id===line.payroll_period_id)!;const treasury=mb.treasury_accounts.find(x=>x.id===input.treasury_account_id&&x.business_unit_id===line.business_unit_id&&x.active);if(!treasury)throw new Error('treasury_account_not_found');const amount=Math.min(line.balance_sar,input.amount_sar??line.balance_sar);if(amount<=0)throw new Error('payroll_payment_invalid');let nextWeb=ensureWorkforceFinanceV2025(web,mb,state),cc=line.cost_allocations[0]?.cost_center_id;nextWeb=postJournalV202(nextWeb,{journal_date:input.payment_date,description:`Payroll payment ${line.payroll_number}`,source_type:'payroll_payment_v20_2_5',source_id:line.id,original_currency:'SAR',original_amount:amount,exchange_rate_to_sar:1,rate_date:input.payment_date,lines:[{account_code:'2100',account_name:'Payroll Payable',debit_sar:amount,credit_sar:0,cost_center_id:cc,counterparty:line.employee_id},{account_code:'1000',account_name:'Cash & Banks',debit_sar:0,credit_sar:amount,cost_center_id:cc}],created_by:input.paid_by,approved_by:period.approved_by||input.paid_by},'finance');let nextMb=addTreasuryMovement(mb,{treasury_account_id:treasury.id,business_unit_id:line.business_unit_id,direction:'out',original_currency:'SAR',original_amount:amount,exchange_rate_to_sar:1,amount_sar:amount,source_type:'payroll_payment',source_id:line.id,occurred_at:now(),actor_user_id:input.paid_by});const payment:PayrollPaymentV2025={id:rid('PPAY'),payment_number:serial('PPAY'),payroll_period_id:line.payroll_period_id,payroll_line_id:line.id,employee_id:line.employee_id,business_unit_id:line.business_unit_id,treasury_account_id:treasury.id,payment_date:input.payment_date,currency:'SAR',original_amount:amount,exchange_rate_to_sar:1,amount_sar:amount,paid_by:input.paid_by,journal_entry_id:nextWeb.journal_entries[0].id,created_at:now()};const balance=round(line.balance_sar-amount),updated={...line,paid_sar:round(line.paid_sar+amount),balance_sar:balance,status:(balance===0?'paid':'partially_paid') as PayrollStatusV2025};let next=audit({...state,payroll_lines:state.payroll_lines.map(x=>x.id===line.id?updated:x),payroll_payments:[payment,...state.payroll_payments]},input.paid_by,'payroll_payment','payroll_payment',payment.id,undefined,payment);const periodLines=next.payroll_lines.filter(x=>x.payroll_period_id===period.id),periodStatus=periodLines.every(x=>x.status==='paid')?'paid':periodLines.some(x=>x.paid_sar>0)?'partially_paid':period.status;next={...next,payroll_periods:next.payroll_periods.map(x=>x.id===period.id?{...x,status:periodStatus as PayrollStatusV2025}:x)};return {state:next,multiBusiness:nextMb,web:nextWeb,payment};}

export function createTransportTripV2025(state:WorkforcePayrollStateV2025,web:EnterpriseWebStateV202,mb:MultiBusinessEnterpriseStateV2023,input:Omit<TransportTripV2025,'id'|'trip_number'|'created_at'|'journal_entry_id'>,actor:string):{state:WorkforcePayrollStateV2025;web:EnterpriseWebStateV202;trip:TransportTripV2025}{const unit=requireUnit(mb,input.business_unit_id);if(input.driver_employee_id)requireProfile(state,input.driver_employee_id);const tripId=rid('TRIP'),tripNumber=serial('TRIP'),createdAt=now(),total=round(input.transport_fee_sar+input.fuel_cost_sar+input.loading_cost_sar);let nextWeb=ensureWorkforceFinanceV2025(web,mb,state);let journalId:string|undefined;if(input.status==='completed'&&total>0){const cc=input.cost_center_id||nextWeb.cost_centers.find(x=>x.code===unit.cost_center_code)?.id;nextWeb=postJournalV202(nextWeb,{journal_date:input.trip_date,description:`Transport ${input.from_location} → ${input.to_location}`,source_type:'transport_trip_v20_2_5',source_id:tripId,original_currency:'SAR',original_amount:total,exchange_rate_to_sar:1,rate_date:input.trip_date,lines:[{account_code:'5410',account_name:'Field Travel & Transport',debit_sar:total,credit_sar:0,cost_center_id:cc},{account_code:'2000',account_name:'Accounts Payable',debit_sar:0,credit_sar:total,cost_center_id:cc,counterparty:input.driver_employee_id}],created_by:actor,approved_by:actor},'finance');journalId=nextWeb.journal_entries[0].id;}const row:TransportTripV2025={...input,id:tripId,trip_number:tripNumber,created_at:createdAt,journal_entry_id:journalId};return {state:audit({...state,transport_trips:[row,...state.transport_trips]},actor,'transport_trip_create','transport_trip',row.id,undefined,row),web:nextWeb,trip:row};}
export function allocateFactoryLaborV2025(state:WorkforcePayrollStateV2025,feed:FeedFactoryOperationsStateV2024,mb:MultiBusinessEnterpriseStateV2023,input:{factory_id:string;manufacturing_order_id:string;employee_id:string;attendance_id?:string;work_date:string;hours:number;labor_cost_sar:number;allocated_by:string}):WorkforcePayrollStateV2025{if(!state.settings.factory_labor_capture_enabled)throw new Error('factory_labor_capture_disabled');const factory=mb.factories.find(x=>x.id===input.factory_id);if(!factory)throw new Error('factory_not_found');const order=feed.manufacturing_orders.find(x=>x.id===input.manufacturing_order_id&&x.factory_id===factory.id);if(!order)throw new Error('manufacturing_order_not_found');const p=requireProfile(state,input.employee_id);if(!['factory_worker','production_supervisor'].includes(p.job_family))throw new Error('factory_labor_employee_required');if(input.hours<=0||input.labor_cost_sar<0)throw new Error('invalid_factory_labor');const row:FactoryLaborAllocationV2025={id:rid('FLAB'),allocation_number:serial('FLAB'),factory_id:factory.id,manufacturing_order_id:order.id,employee_id:p.employee_id,attendance_id:input.attendance_id,work_date:input.work_date,hours:input.hours,labor_cost_sar:input.labor_cost_sar,allocated_by:input.allocated_by,created_at:now()};return audit({...state,factory_labor_allocations:[row,...state.factory_labor_allocations]},input.allocated_by,'factory_labor_allocate','factory_labor_allocation',row.id,undefined,row);}
export function manufacturingLaborCostV2025(state:WorkforcePayrollStateV2025,manufacturingOrderId:string){return round(state.factory_labor_allocations.filter(x=>x.manufacturing_order_id===manufacturingOrderId).reduce((s,x)=>s+x.labor_cost_sar,0));}
export function registerEmployeeDocumentV2025(state:WorkforcePayrollStateV2025,input:Omit<EmployeeDocumentV2025,'id'|'created_at'>){requireProfile(state,input.employee_id);const row:EmployeeDocumentV2025={...input,id:rid('EDOC'),created_at:now()};return audit({...state,employee_documents:[row,...state.employee_documents]},input.uploaded_by,'employee_document_register','employee_document',row.id,undefined,row);}
