export function employee360V2025(state:WorkforcePayrollStateV2025,employeeId:string){const profile=requireProfile(state,employeeId),assignments=state.assignments.filter(x=>x.employee_id===profile.employee_id),contracts=state.compensation_contracts.filter(x=>x.employee_id===profile.employee_id),advances=state.advances.filter(x=>x.employee_id===profile.employee_id),payroll=state.payroll_lines.filter(x=>x.employee_id===profile.employee_id),attendance=state.attendance.filter(x=>x.employee_id===profile.employee_id),leave=state.leave_requests.filter(x=>x.employee_id===profile.employee_id),documents=state.employee_documents.filter(x=>x.employee_id===profile.employee_id);return {profile,assignments,contracts,attendance:attendance.slice(0,60),leave,advances,payroll,payroll_paid_sar:round(payroll.reduce((s,x)=>s+x.paid_sar,0)),payroll_outstanding_sar:round(payroll.reduce((s,x)=>s+x.balance_sar,0)),advance_balance_sar:round(advances.reduce((s,x)=>s+x.balance_sar,0)),documents};}
export function workforceDashboardV2025(state:WorkforcePayrollStateV2025,mb:MultiBusinessEnterpriseStateV2023,businessUnitId?:string){const profiles=state.profiles.filter(p=>!businessUnitId||p.home_business_unit_id===businessUnitId||state.assignments.some(a=>a.employee_id===p.employee_id&&a.business_unit_id===businessUnitId&&a.active)),ids=new Set(profiles.map(x=>x.employee_id)),contracts=state.compensation_contracts.filter(x=>ids.has(x.employee_id)&&x.status==='active'),lines=state.payroll_lines.filter(x=>ids.has(x.employee_id)),today=now().slice(0,10),expiring=contracts.filter(x=>x.end_date&&x.end_date>=today&&x.end_date<=new Date(Date.now()+30*86400000).toISOString().slice(0,10));return {business_unit:businessUnitId?mb.business_units.find(x=>x.id===businessUnitId):undefined,active_employees:profiles.filter(x=>x.employment_status==='active').length,doctors:profiles.filter(x=>['veterinarian','consultant'].includes(x.job_family)).length,workers:profiles.filter(x=>x.job_family==='worker').length,factory_staff:profiles.filter(x=>['factory_worker','production_supervisor'].includes(x.job_family)).length,payroll_gross_sar:round(lines.reduce((s,x)=>s+currencyAmountToSar(x.gross_pay,x.exchange_rate_to_sar),0)),payroll_outstanding_sar:round(lines.reduce((s,x)=>s+x.balance_sar,0)),advance_balance_sar:round(state.advances.filter(x=>ids.has(x.employee_id)).reduce((s,x)=>s+x.balance_sar,0)),contracts_expiring_30d:expiring.length,leave_pending:state.leave_requests.filter(x=>ids.has(x.employee_id)&&x.status==='requested').length,advances_pending:state.advances.filter(x=>ids.has(x.employee_id)&&x.status==='requested').length,payroll_periods:state.payroll_periods.filter(x=>!businessUnitId||x.business_unit_id===businessUnitId).slice(0,12)};}
export function payrollRegisterV2025(state:WorkforcePayrollStateV2025,periodId:string){const period=state.payroll_periods.find(x=>x.id===periodId);if(!period)throw new Error('payroll_period_not_found');return {period,lines:state.payroll_lines.filter(x=>x.payroll_period_id===period.id).map(x=>({...x,employee:state.profiles.find(p=>p.employee_id===x.employee_id)})),gross_sar:round(state.payroll_lines.filter(x=>x.payroll_period_id===period.id).reduce((s,x)=>s+currencyAmountToSar(x.gross_pay,x.exchange_rate_to_sar),0)),net_sar:round(state.payroll_lines.filter(x=>x.payroll_period_id===period.id).reduce((s,x)=>s+x.net_pay_sar,0)),paid_sar:round(state.payroll_lines.filter(x=>x.payroll_period_id===period.id).reduce((s,x)=>s+x.paid_sar,0))};}

export function validateWorkforcePayrollStateV2025(state:WorkforcePayrollStateV2025,mb:MultiBusinessEnterpriseStateV2023,web?:EnterpriseWebStateV202,feed?:FeedFactoryOperationsStateV2024):string[]{const issues:string[]=[];const uniq=(rows:string[],label:string)=>{const seen=new Set<string>();for(const x of rows){if(seen.has(x))issues.push(`${label}_duplicate:${x}`);seen.add(x)}};uniq(state.profiles.map(x=>x.employee_number),'employee_number');uniq(state.assignments.map(x=>x.assignment_number),'assignment_number');uniq(state.advances.map(x=>x.advance_number),'advance_number');uniq(state.payroll_lines.map(x=>x.payroll_number),'payroll_number');const unitIds=new Set(mb.business_units.map(x=>x.id)),empIds=new Set(state.profiles.map(x=>x.employee_id));for(const p of state.profiles)if(!unitIds.has(p.home_business_unit_id))issues.push(`employee_orphan_business_unit:${p.employee_id}`);for(const a of state.assignments){if(!empIds.has(a.employee_id))issues.push(`assignment_orphan_employee:${a.id}`);if(!unitIds.has(a.business_unit_id))issues.push(`assignment_orphan_business_unit:${a.id}`);if(a.allocation_percent<=0||a.allocation_percent>100)issues.push(`assignment_invalid_allocation:${a.id}`);}for(const c of state.compensation_contracts){if(!empIds.has(c.employee_id))issues.push(`contract_orphan_employee:${c.id}`);const total=round(c.payer_breakdown.reduce((s,x)=>s+x.percent,0),4);if(Math.abs(total-100)>0.001)issues.push(`contract_payer_not_100:${c.id}`);}for(const l of state.payroll_lines){if(!empIds.has(l.employee_id))issues.push(`payroll_orphan_employee:${l.id}`);if(l.net_pay_sar<0||l.balance_sar<0)issues.push(`payroll_negative_amount:${l.id}`);if(l.paid_sar-l.net_pay_sar>0.01)issues.push(`payroll_overpaid:${l.id}`);}for(const a of state.advances){if(a.balance_sar<0||a.recovered_sar-a.amount_sar>0.01)issues.push(`advance_invalid_balance:${a.id}`);}if(feed)for(const a of state.factory_labor_allocations)if(!feed.manufacturing_orders.some(x=>x.id===a.manufacturing_order_id))issues.push(`factory_labor_orphan_order:${a.id}`);if(web){const next=ensureWorkforceFinanceV2025(web,mb,state);for(const code of WORKFORCE_ACCOUNTS.map(x=>x.code))if(!next.chart_of_accounts.some(a=>a.code===code))issues.push(`workforce_account_missing:${code}`);for(const j of next.journal_entries.filter(x=>x.status==='posted')){const d=j.lines.reduce((s,l)=>s+l.debit_sar,0),c=j.lines.reduce((s,l)=>s+l.credit_sar,0);if(Math.abs(d-c)>0.01)issues.push(`unbalanced_journal:${j.id}`);}}return issues;}
